DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_type WHERE typname='unit_leasing_status') THEN CREATE TYPE public.unit_leasing_status AS ENUM('available','on_hold','pending_contract','leased','maintenance','blocked'); END IF; END $$;
ALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'leasing_manager';
ALTER TABLE public.units ADD COLUMN IF NOT EXISTS leasing_status public.unit_leasing_status;
ALTER TABLE public.units ADD COLUMN IF NOT EXISTS leasing_status_initialized boolean NOT NULL DEFAULT false;
ALTER TABLE public.bookings ADD COLUMN IF NOT EXISTS hold_extensions integer NOT NULL DEFAULT 0;
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS hold_hours integer NOT NULL DEFAULT 48;
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS max_hold_extensions integer NOT NULL DEFAULT 1;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS archived_at timestamptz;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS archived_by uuid;
ALTER TABLE public.tenants ADD COLUMN IF NOT EXISTS archive_reason text;
ALTER TABLE public.booking_units ADD COLUMN IF NOT EXISTS archived_at timestamptz;
ALTER TABLE public.booking_units ADD COLUMN IF NOT EXISTS archived_by uuid;
ALTER TABLE public.booking_units ADD COLUMN IF NOT EXISTS archive_reason text;
CREATE TABLE IF NOT EXISTS public.unit_status_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),unit_id uuid NOT NULL REFERENCES public.units(id),from_status public.unit_leasing_status,to_status public.unit_leasing_status,actor uuid,actor_role text,reason text NOT NULL,ref_type text NOT NULL,ref_id uuid,at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.unit_status_history TO authenticated;
GRANT ALL ON public.unit_status_history TO service_role;
ALTER TABLE public.unit_status_history ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.unit_status_backfill_review(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),unit_id uuid UNIQUE NOT NULL REFERENCES public.units(id),original_status text NOT NULL,proposed_status public.unit_leasing_status,reason text NOT NULL,evidence jsonb NOT NULL DEFAULT '{}',resolved_at timestamptz,resolved_by uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.unit_status_backfill_review TO authenticated;
GRANT ALL ON public.unit_status_backfill_review TO service_role;
ALTER TABLE public.unit_status_backfill_review ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.unit_contracts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),unit_id uuid NOT NULL REFERENCES public.units(id),booking_id uuid REFERENCES public.bookings(id),tenant_account_id uuid REFERENCES public.tenant_accounts(id),contract_number text NOT NULL,status text NOT NULL DEFAULT 'draft',starts_on date,ends_on date,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),status_reason text NOT NULL);
GRANT SELECT ON public.unit_contracts TO authenticated;
GRANT ALL ON public.unit_contracts TO service_role;
ALTER TABLE public.unit_contracts ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.unit_first_payment_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contract_id uuid NOT NULL REFERENCES public.unit_contracts(id),receipt_type text NOT NULL,receipt_id uuid NOT NULL,verified_by uuid NOT NULL,reason text NOT NULL,verified_at timestamptz NOT NULL DEFAULT now(),UNIQUE(contract_id,receipt_type,receipt_id));
GRANT SELECT ON public.unit_first_payment_verifications TO authenticated;
GRANT ALL ON public.unit_first_payment_verifications TO service_role;
ALTER TABLE public.unit_first_payment_verifications ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['unit_status_history','unit_status_backfill_review','unit_contracts','unit_first_payment_verifications'] LOOP
IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename=t AND policyname='unit_leasing_admin_read') THEN EXECUTE format('CREATE POLICY unit_leasing_admin_read ON public.%I FOR SELECT TO authenticated USING (public.has_role(auth.uid(),''admin'') OR public.has_role(auth.uid(),''manager''))',t); END IF;
END LOOP; END $$;
CREATE INDEX IF NOT EXISTS unit_status_history_unit_at ON public.unit_status_history(unit_id,at DESC,id);
CREATE UNIQUE INDEX IF NOT EXISTS unit_contracts_one_active ON public.unit_contracts(unit_id) WHERE status='active';
SELECT table_name,column_name FROM information_schema.columns WHERE table_schema='public' AND column_name IN ('leasing_status','hold_hours','max_hold_extensions','hold_extensions');
